import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"49、【革】 离下兑上","description":"横渠易说 - 49、【革】 离下兑上","frontmatter":{"title":"49、【革】 离下兑上","description":"横渠易说 - 49、【革】 离下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/051.md","filePath":"zh/classics/hengqu/051.md"}'),l={name:"zh/classics/hengqu/051.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_49、【革】-离下兑上" tabindex="-1">49、【革】 离下兑上 <a class="header-anchor" href="#_49、【革】-离下兑上" aria-label="Permalink to “49、【革】 离下兑上”">​</a></h1><h3 id="彖曰-革-水火相息-二女同居-其志不相得曰革。-巳日乃孚-革而信之-文明以说-大亨以正。革而当-其悔乃亡。" tabindex="-1">彖曰：革，水火相息，二女同居，其志不相得曰革。“巳日乃孚”，革而信之，文明以说，大亨以正。革而当，其悔乃亡。 <a class="header-anchor" href="#彖曰-革-水火相息-二女同居-其志不相得曰革。-巳日乃孚-革而信之-文明以说-大亨以正。革而当-其悔乃亡。" aria-label="Permalink to “彖曰：革，水火相息，二女同居，其志不相得曰革。“巳日乃孚”，革而信之，文明以说，大亨以正。革而当，其悔乃亡。”">​</a></h3><h3 id="天地革而四时成-汤武革命-顺乎天而应乎人。革之时大矣哉-象曰-泽中有火-革-君子以治历明时。" tabindex="-1">天地革而四时成，汤武革命，顺乎天而应乎人。革之时大矣哉! 象曰：泽中有火，革，君子以治历明时。 <a class="header-anchor" href="#天地革而四时成-汤武革命-顺乎天而应乎人。革之时大矣哉-象曰-泽中有火-革-君子以治历明时。" aria-label="Permalink to “天地革而四时成，汤武革命，顺乎天而应乎人。革之时大矣哉! 象曰：泽中有火，革，君子以治历明时。”">​</a></h3><h3 id="初九-巩用黄牛之革。-象曰-巩用黄牛-不可以有为也。" tabindex="-1">初九，巩用黄牛之革。 象曰：“巩用黄牛”，不可以有为也。 <a class="header-anchor" href="#初九-巩用黄牛之革。-象曰-巩用黄牛-不可以有为也。" aria-label="Permalink to “初九，巩用黄牛之革。 象曰：“巩用黄牛”，不可以有为也。”">​</a></h3><p>贱而无应，非大亨以正之德中坚自守，不可有为。</p><h3 id="六二-巳日乃革之-征吉无咎。-象曰-巳日革之-行有嘉也。" tabindex="-1">六二，巳日乃革之，征吉无咎。 象曰：“巳日革之”，行有嘉也。 <a class="header-anchor" href="#六二-巳日乃革之-征吉无咎。-象曰-巳日革之-行有嘉也。" aria-label="Permalink to “六二，巳日乃革之，征吉无咎。 象曰：“巳日革之”，行有嘉也。”">​</a></h3><p>俟上之唱，革而往应，柔中之德，所之乃吉。</p><h3 id="九三-征凶贞厉-革言三就-有孚。-象曰-革言三就-又何之矣" tabindex="-1">九三，征凶贞厉，革言三就，有孚。 象曰：“革言三就”，又何之矣! <a class="header-anchor" href="#九三-征凶贞厉-革言三就-有孚。-象曰-革言三就-又何之矣" aria-label="Permalink to “九三，征凶贞厉，革言三就，有孚。 象曰：“革言三就”，又何之矣!”">​</a></h3><p>以文明炎上刚阳之德进而之兑，兑内柔外刚，势穷必反，故以征则凶。能守正戒惧，文命告之，此三革言，彼三从命，必然可信之理也。一云：征则虽正而危。</p><h3 id="九四-悔亡有孚。改命吉。-象曰-改命之吉-信志也。" tabindex="-1">九四，悔亡有孚。改命吉。 象曰：改命之吉，信志也。 <a class="header-anchor" href="#九四-悔亡有孚。改命吉。-象曰-改命之吉-信志也。" aria-label="Permalink to “九四，悔亡有孚。改命吉。 象曰：改命之吉，信志也。”">​</a></h3><p>约己居阴，心无私系，革而必当，见孚于众，改命倡始，信己可行，故吉。</p><h3 id="九五-大人虎变-未占有孚。-象曰-大人虎变-其文炳也。" tabindex="-1">九五，大人虎变，未占有孚。 象曰：“大人虎变”，其文炳也。 <a class="header-anchor" href="#九五-大人虎变-未占有孚。-象曰-大人虎变-其文炳也。" aria-label="Permalink to “九五，大人虎变，未占有孚。 象曰：“大人虎变”，其文炳也。”">​</a></h3><p>以刚居尊，说而唱下，为众所睹，其文炳然，不卜而孚，望而可信，下观而化，革着盛焉。 大人虎变，夫何疚之有! 虎变文章大，故明；豹变文章小，故蔚。</p><h3 id="上六-君子豹变-小人革面-征凶-居贞吉。-象曰-君子豹变-其文蔚也-小人革面-顺以从君也。" tabindex="-1">上六，君子豹变，小人革面，征凶，居贞吉。 象曰：“君子豹变”，其文蔚也；“小人革面”，顺以从君也。 <a class="header-anchor" href="#上六-君子豹变-小人革面-征凶-居贞吉。-象曰-君子豹变-其文蔚也-小人革面-顺以从君也。" aria-label="Permalink to “上六，君子豹变，小人革面，征凶，居贞吉。 象曰：“君子豹变”，其文蔚也；“小人革面”，顺以从君也。”">​</a></h3><p>以柔为德，不及九五刚中炳明，故但文章蔚缛，能使小人改观而从也。 盛德之容，颜孟以上始可以观。若颜子变则必大变，即大人虎变，虎变则其文至也，如此则不待占而有信。君子所至之分以致文，则足以为班班之缛。革面而听命，已不敢犯，此所谓尽饰之道，斯行者远矣，然犹是就小成上以致其文。颜子地位，于豹变已为亵就，未必肯于此发见，此所以如愚。愚虽是于吾言无所不说，然必夫子省其私，始知不愚，察其人焉，惟是徇内尚质尔。然发则不小发， 大抵止乃有光明，艮曰“时止则止，时行则行，其道光明”，形则着，着则明，必能止则有光明。今作事特未决，盖非止也，止乃决为，然后就其上文章。颜子见其进，未见其止，未止故未发见其所止，又必欲如所期，盖未见夫子着心处，故未肯止，是之谓隐而未见，行而未成，是以勿用。学者至此地位，亦必如愚。然颜子(学)举措亦无不致文中节处，自(是)谓“博我以文”，则文岂不足？但颜子不以为意，所谓“有若无，实若虚”也。有颜子之心，则不为颜子之文可也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
